import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import collections, csv
recs = collections.defaultdict(set)
for r in csv.DictReader(open("kb/_self/reports/benchmarks.csv", encoding="utf-8")):
    if r["scenario"] == "multi" and r["metric"] == "dedup_hits" and r["arm"].startswith("concurrent"):
        co = "shared" if "coord=shared" in r["arm"] else "isolated" if "coord=isolated" in r["arm"] else ""
        recs[(r["case"], co)].add((r["record"], r["note"].rsplit("run started", 1)[-1]))
need = {(c, o): len(recs[(c, o)]) for c in ("research", "coord") for o in ("shared", "isolated") if len(recs[(c, o)]) < 2}
assert not need, ("fewer than two recorded runs with dedup_hits", need)
